export function FilteredView({
  heading = "{{heading}}",
  filterLabel = "{{filterLabel}}",
  activeFilter = "{{activeFilter}}",
  accent = "{{accent}}",
  resultCount = {{resultCount}},
}) {
  const chip = (value, label) => (
    <button type="button" key={value} style={{ background: activeFilter === value ? accent : "#fff", borderColor: activeFilter === value ? "transparent" : "#24143020", border: "1px solid", borderRadius: 999, padding: "5px 12px", font: "inherit", fontWeight: 600, cursor: "pointer" }}>{label}</button>
  );
  return (
    <section aria-label={heading} style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", background: "#FAF7F2", maxWidth: 320, width: 320, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <div role="group" aria-label={filterLabel} style={{ display: "flex", gap: 6, marginBottom: 8 }}>
        {chip("all", "All")}
        {chip("active", "Active")}
        {chip("archived", "Archived")}
      </div>
      <p role="status" style={{ margin: "0 0 8px", fontSize: 12, color: "#241430a0" }}>Showing {activeFilter} — {resultCount} results</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        <li style={{ padding: "8px 10px", background: "#fff", borderRadius: 8, marginBottom: 6 }}>Homepage redesign</li>
        <li style={{ padding: "8px 10px", background: "#fff", borderRadius: 8, marginBottom: 6 }}>Q3 roadmap</li>
        <li style={{ padding: "8px 10px", background: "#fff", borderRadius: 8 }}>Support backlog</li>
      </ul>
    </section>
  );
}
